import sys

def min_time_to_house(n, a):
    if a == 1 or a == n:
        return 1
    if a % 2 == 1:
        # Odd house
        return (a + 1) // 2
    else:
        # Even house
        return n // 2 - (a // 2) + 1

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    a = int(data[1])
    print(min_time_to_house(n, a))

if __name__ == "__main__":
    main()
